CREATE VIEW mart_game_discovery_v1 AS SELECT c.GameKey, c.GameID, c.GameTitle, c.PlayStatusName, c.final_recommendation_score, c.playability_status, c.recommendation_status, c.recommendation_context FROM mart_recommendation_context_v1 AS c WHERE ((c.recommendation_context = 'Discovery Candidate') AND (c.final_recommendation_score IS NOT NULL)) ORDER BY c.final_recommendation_score DESC;
